<?php
$monthStart=$goalPerformance['monthStart'];$calendar=$goalPerformance['calendar'];$firstDow=(int)$monthStart->format('N');$dailyGoal=(float)$goalPerformance['dailyGoal'];$selectedAccount=$selectedAccount??null;$selectedSystem=$selectedSystem??null;$prevMonth=$monthStart->modify('-1 month')->format('Y-m');$nextMonth=$monthStart->modify('+1 month')->format('Y-m');$calendarQuery=function(string $month)use($selectedAccount,$selectedSystem):string{$p=['month'=>$month];if($selectedAccount!==null)$p['account']=$selectedAccount;if($selectedSystem!==null)$p['system']=$selectedSystem;return http_build_query($p);};
?>
<div id="calendar-section" class="card"><div class="section-heading calendar-title"><div><h2>Monthly P&amp;L Calendar — <?=e($monthStart->format('F Y'))?></h2><div class="calendar-legend" aria-label="Calendar P&amp;L status legend"><span class="calendar-legend-item goal"><span class="calendar-legend-symbol">✓</span><span>Goal hit</span></span><span class="calendar-legend-item positive"><span class="calendar-legend-symbol">↑</span><span>Positive below goal</span></span><span class="calendar-legend-item loss"><span class="calendar-legend-symbol">✕</span><span>Loss</span></span><span class="calendar-legend-item flat"><span class="calendar-legend-symbol">•</span><span>No P&amp;L</span></span></div></div><div class="calendar-nav"><a class="secondary-link" href="?<?=e($calendarQuery($prevMonth))?>" data-calendar-month="<?=$prevMonth?>">← Prev</a><a class="secondary-link" href="?<?=e($calendarQuery(date('Y-m')))?>" data-calendar-month="<?=date('Y-m')?>">Today</a><a class="secondary-link" href="?<?=e($calendarQuery($nextMonth))?>" data-calendar-month="<?=$nextMonth?>">Next →</a></div></div><div class="pnl-calendar"><div class="calendar-head"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div><div class="calendar-grid"><?php for($i=1;$i<$firstDow;$i++):?><div class="calendar-day empty"></div><?php endfor;foreach($calendar as $date=>$pnl):$day=(int)substr($date,8,2);$hit=$dailyGoal>0&&(float)$pnl>=$dailyGoal;$mark=$hit?'✓':($pnl<0?'✕':($pnl>0?'↑':'•'));?><div class="calendar-day <?=$hit?'goal-hit':($pnl>0?'profit':($pnl<0?'loss':'flat'))?>"><span class="calendar-date"><?=$day?> <b class="calendar-mark <?=$hit?'goal':($pnl<0?'loss':($pnl>0?'positive':'flat'))?>"><?=$mark?></b></span><strong><?=number_format($pnl,2)?></strong><?php if($dailyGoal>0):?><small>Goal <?=number_format($dailyGoal,2)?></small><?php endif;?></div><?php endforeach;?></div></div></div>